sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading) return;
    if (newValue === 'access_request' || newValue === 'equipment') {
        g_form.setMandatory('description', true);
        g_form.addInfoMessage('Please provide detailed justification for ' + g_form.getDisplayValue('request_type') + ' requests.');
    } else {
        g_form.setMandatory('description', false);
        g_form.clearMessages();
    }
    if (newValue === 'onboarding' || newValue === 'offboarding') {
        g_form.setMandatory('due_date', true);
    } else {
        g_form.setMandatory('due_date', false);
    }
}
